"use client";

import * as React from "react";
import { useMorph } from "@/lib/cojeev-motion/use-morph";
import { cva, type VariantProps } from "class-variance-authority";
import { cn } from "@/lib/utils";
import {
  controlRadiusStyle,
  type ControlRadius,
} from "@/lib/cojeev/control-appearance";

const badgeVariants = cva(
  "v-badge inline-flex items-center justify-center gap-[6px] rounded-[var(--r-pill)] leading-none whitespace-nowrap bg-[var(--v-beige)] text-[color:var(--v-text)] tracking-[.005em]",
  {
    variants: {
      variant: {
        default: "",
        pink: "-pink bg-[var(--v-pink)] text-[color:var(--v-on-accent)] [--muted-foreground:var(--muted-foreground-ink)]",
        yellow:
          "-yellow bg-[var(--status-warn-bg)] text-[color:var(--status-warn-ink)] [--muted-foreground:var(--muted-foreground-ink)]",
        olive:
          "-olive bg-[var(--status-ok-bg)] text-[color:var(--status-ok-ink)] [--muted-foreground:var(--muted-foreground-ink)]",
        blue: "-blue bg-[var(--status-info-bg)] text-[color:var(--status-info-ink)] [--muted-foreground:var(--muted-foreground-ink)]",
        ink: "-ink bg-[var(--v-ink)] text-[color:var(--v-on-ink)]",
        cream: "-cream bg-[var(--v-canvas)]",
        "pink-soft":
          "-pink-soft bg-[var(--v-pink-soft)] [--muted-foreground:var(--muted-foreground-tinted)]",
        "yellow-soft":
          "-yellow-soft bg-[var(--v-yellow-soft)] [--muted-foreground:var(--muted-foreground-tinted)]",
        "olive-soft":
          "-olive-soft bg-[var(--v-olive-soft)] [--muted-foreground:var(--muted-foreground-tinted)]",
        "blue-soft":
          "-blue-soft bg-[var(--v-blue-soft)] [--muted-foreground:var(--muted-foreground-tinted)]",
        danger:
          "-danger bg-[var(--status-danger-bg)] text-[color:var(--status-danger-ink)]",
        pending: "-pending bg-[var(--v-ink)] text-[color:var(--v-on-ink)]",
        count:
          "-count min-w-[22px] bg-[var(--v-ink)] text-[color:var(--v-on-ink)] tabular-nums",
        dashed:
          "-dashed bg-[var(--v-canvas)] border border-dashed border-[var(--v-edge)]",
        caps: "-caps uppercase tracking-[.08em]",
        test: "-test bg-[var(--v-canvas)] border-[1.5px] border-solid border-[var(--v-ink)] tracking-[.03em]",
        live: "-live bg-[var(--v-canvas)] [box-shadow:inset_0_0_0_1px_var(--v-edge)]",
      },
      size: { default: "", sm: "-sm", lg: "-lg" },
    },
    defaultVariants: { variant: "default", size: "default" },
  },
);
// Later reference rules deliberately override sizes for count/caps/dashed/test.
const badgeDimensions = cva("", {
  variants: {
    dimension: {
      default: "h-[26px] px-[11px] py-0 text-[12.5px] font-medium",
      sm: "h-[20px] px-[8px] py-0 text-[11px] font-semibold",
      lg: "h-[32px] px-[14px] py-0 text-[13.5px] font-medium",
      count: "h-[22px] px-[7px] py-0 text-[11px] font-semibold",
      caps: "h-[26px] px-[11px] py-0 text-[10.5px] font-semibold",
    },
  },
});

type BadgeProps = React.ComponentProps<"span"> &
  VariantProps<typeof badgeVariants> & {
    appearance?: "stamp" | "tag" | "counter";
    radius?: ControlRadius;
  };
const badgeFaces: Record<string, string> = {
  default: "var(--v-beige)",
  pink: "var(--v-pink)",
  yellow: "var(--status-warn-bg)",
  olive: "var(--status-ok-bg)",
  blue: "var(--status-info-bg)",
  ink: "var(--v-ink)",
  cream: "var(--v-canvas)",
  "pink-soft": "var(--v-pink-soft)",
  "yellow-soft": "var(--v-yellow-soft)",
  "olive-soft": "var(--v-olive-soft)",
  "blue-soft": "var(--v-blue-soft)",
  danger: "var(--status-danger-bg)",
  pending: "var(--v-ink)",
  count: "var(--v-ink)",
  dashed: "var(--v-canvas)",
  caps: "var(--v-beige)",
  test: "var(--v-canvas)",
  live: "var(--v-canvas)",
};
function Badge({
  ref: externalRef,
  className,
  variant = "default",
  size = "default",
  appearance,
  radius,
  style,
  ...props
}: BadgeProps) {
  const morphRef = useMorph<HTMLSpanElement>("pills", externalRef);
  const dimension =
    variant === "count" || variant === "caps" ? variant : (size ?? "default");
  return (
    <span
      ref={morphRef}
      data-slot="badge"
      data-part="root"
      data-state="rest"
      data-appearance={appearance}
      data-morph={appearance ? "both" : undefined}
      data-r={appearance ? "css" : undefined}
      data-dash={appearance === "stamp" ? "2 3" : undefined}
      style={{
        ...((appearance
          ? { "--badge-face": badgeFaces[variant ?? "default"] }
          : {}) as React.CSSProperties),
        ...style,
        ...controlRadiusStyle(radius),
      }}
      className={cn(
        badgeVariants({ variant, size }),
        badgeDimensions({ dimension }),
        (variant === "dashed" || variant === "test") && "h-[26px] px-[11px]",
        (variant === "test" || variant === "danger") && "font-semibold",
        "leading-none",
        className,
      )}
      {...props}
    />
  );
}
function BadgeIndicator({ className, ...props }: React.ComponentProps<"span">) {
  return (
    <span
      data-slot="badge-indicator"
      data-part="indicator"
      aria-hidden="true"
      className={cn(
        "v-dot size-[7px] [border-radius:50%] flex-none m-0 bg-current",
        className,
      )}
      {...props}
    />
  );
}
export { Badge, BadgeIndicator, badgeVariants };
export type { BadgeProps };

@layer cojeev-states {
/* Descendant paint and explicit dark overrides from alive.css. */
[data-slot="badge"] > * {
  line-height: 1;
}
.v-badge[data-slot].-caps {
  height: 26px;
  padding: 0 11px;
  font-size: 10.5px;
  font-weight: 600;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}
[data-slot="badge"] .v-dot {
  width: 7px;
  height: 7px;
  border-radius: 50%;
  flex: none;
  margin: 0;
  background: currentColor;
}
[data-slot="badge"]:is(.-live, .-pending) .v-dot {
  background: var(--v-olive);
}
:root[data-mode="dark"]
  [data-slot="badge"]:is(
    .-pink-soft,
    .-yellow-soft,
    .-olive-soft,
    .-blue-soft
  ) {
  color: var(--v-text);
  background: color-mix(in oklab, var(--badge-tint) 20%, var(--v-canvas));
}
:root[data-mode="dark"] [data-slot="badge"].-pink-soft {
  --badge-tint: var(--v-pink);
}
:root[data-mode="dark"] [data-slot="badge"].-yellow-soft {
  --badge-tint: var(--v-yellow);
}
:root[data-mode="dark"] [data-slot="badge"].-olive-soft {
  --badge-tint: var(--v-olive);
}
:root[data-mode="dark"] [data-slot="badge"].-blue-soft {
  --badge-tint: var(--v-blue);
}
:root[data-mode="dark"] [data-slot="badge"]:is(.-dashed, .-test, .-live) {
  background: var(--v-beige-2);
}
/* The moving SVG owns this edge; a painted DOM edge would double it. */
[data-slot="badge"]:is(.-dashed, .-test).v-morph-live {
  border-color: transparent;
}

/* Shape and paint are independent of the status/tone axis. The SVG owns both. */
.v-badge[data-appearance] {
  --mfill: var(--badge-face);
  --mstroke: currentColor;
  position: relative;
  isolation: isolate;
  border: 0;
  border-radius: var(--v-control-radius, 8px);
  box-shadow: none;
}
.v-badge[data-appearance="stamp"] {
  letter-spacing: 0.045em;
}
.v-badge[data-appearance="tag"] {
  border-radius: var(--v-control-radius, 4px 12px 12px 4px);
}
.v-badge[data-appearance="tag"]::before {
  content: "";
  width: 5px;
  height: 5px;
  border-radius: 50%;
  border: 1px solid currentColor;
  flex: none;
  opacity: 0.6;
}
.v-badge[data-appearance="counter"] {
  border-radius: var(--v-control-radius, 50%);
  min-width: var(--badge-count-size, 28px);
  font-variant-numeric: tabular-nums;
}
.v-badge[data-appearance].v-morph-live {
  background: transparent;
}
:root[data-mode="dark"]
  .v-badge[data-appearance]:is(
    .-pink-soft,
    .-yellow-soft,
    .-olive-soft,
    .-blue-soft
  ) {
  --mfill: color-mix(in oklab, var(--badge-tint) 20%, var(--v-canvas));
}
:root[data-mode="dark"] .v-badge[data-appearance]:is(.-dashed, .-test, .-live) {
  --mfill: var(--v-beige-2);
}
.v-badge-example {
  width: 100%;
  max-width: 620px;
  margin-inline: auto;
  display: grid;
  gap: 22px;
  color: var(--v-text);
}
.v-badge-example__surface {
  position: relative;
  min-width: 0;
  border: 1px solid var(--v-edge);
  border-radius: 20px;
  background: var(--v-paper);
  padding: 28px;
}
.v-badge-example__kicker {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 12px;
  font-size: 11px;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: var(--v-text-3);
}
.v-badge-example__surface h3 {
  font-family: var(--font-display);
  font-size: clamp(24px, 4cqi, 34px);
  line-height: 1.18;
  margin: 22px 0 10px;
}
.v-badge-example__surface p {
  color: var(--v-text-2);
  line-height: 1.6;
  margin: 0;
}
.v-badge-example__surface[data-layout="stamp"] {
  border-radius: 4px 22px 22px 4px;
  border-left: 5px solid var(--v-pink);
}
.v-badge-example__stamp {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: space-between;
  gap: 20px;
  border-top: 1px solid var(--v-edge);
  margin-top: 28px;
  padding-top: 20px;
}
.v-badge-example__stamp .v-badge {
  transform: rotate(-3deg);
  transform-origin: center;
}
.v-badge-example__meta {
  display: grid;
  gap: 6px;
  font-size: 12px;
  color: var(--v-text-3);
}
.v-badge-example__meta strong {
  font-size: 14px;
  font-weight: 500;
  color: var(--v-text);
}
.v-badge-example__tags {
  margin: 26px 0 0;
  display: grid;
  gap: 0;
}
.v-badge-example__tags > div {
  display: flex;
  justify-content: space-between;
  align-items: center;
  flex-wrap: wrap;
  gap: 12px;
  border-top: 1px solid var(--v-edge);
  padding: 14px 0;
}
.v-badge-example__tags dt {
  font-size: 12px;
  color: var(--v-text-3);
}
.v-badge-example__tags dd {
  margin: 0;
}
.v-badge-example__counter {
  display: flex;
  align-items: center;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: 20px;
}
.v-badge-example__counter h3 {
  margin: 0;
}
.v-badge-example__counter .v-badge {
  --badge-count-size: 52px;
  height: 52px;
  padding-inline: 15px;
  font-size: 24px;
}
.v-badge-example__surface[data-layout="counter"] p {
  margin-block: 14px 24px;
}
.v-badge-example__actions {
  display: flex;
  flex-wrap: wrap;
  gap: 10px;
}
.v-badge-example__treatments {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 12px;
}
.v-badge-example__copy {
  display: grid;
  gap: 10px;
}
.v-badge-example__eyebrow {
  color: var(--v-text-3);
  font-size: 11px;
  letter-spacing: 0.05em;
}
.v-badge-example__counter .v-badge.-sm {
  --badge-count-size: 40px;
  height: 40px;
  font-size: 20px;
}
.v-badge-example__counter .v-badge.-lg {
  --badge-count-size: 64px;
  height: 64px;
  font-size: 28px;
}
@container (max-width:440px) {
  .v-badge-example__surface {
    padding: 22px;
  }
}

}

@layer cojeev-states {
/* One inherited corner contract, with a readable cap for multiline/native fields. */
:is(.v-input,.v-igroup,.v-select,.v-native,.v-number-input,.v-btn) {
  border-radius: var(--v-control-radius, var(--r-pill));
}
:is(.v-textarea,.v-composer,.v-native,.v-multi-select__trigger) {
  border-radius: min(var(--v-control-radius, 20px), 20px);
}
.v-btn[data-control-shape="card"] { border-radius: 12px; }
.v-btn[data-control-shape="pill"] { border-radius: var(--r-pill); }

/* A Field can own the treatment for its immediate shell; explicit child paint wins. */
:root .v-native[data-appearance] { padding-inline-end:40px; }
:root .v-native[data-appearance][size]:not([size="1"]) { padding-inline:8px; }
[data-slot="field"][data-appearance="contour"] { --v-field-face: var(--v-canvas); }
:root [data-appearance="contour"]:is(.v-input,.v-igroup,.v-textarea,.v-native,.v-select,.v-number-input,.v-multi-select__trigger),
:root [data-slot="field"][data-appearance="contour"] :is(.v-input,.v-igroup,.v-textarea):not([data-appearance]) {
  background-color: var(--v-canvas);
  color: var(--v-text);
  box-shadow: inset 0 0 0 1px var(--v-edge);
}
:root [data-appearance="editorial"]:is(.v-input,.v-igroup,.v-textarea,.v-native,.v-select,.v-number-input,.v-multi-select__trigger),
:root [data-slot="field"][data-appearance="editorial"] :is(.v-input,.v-igroup,.v-textarea):not([data-appearance]) {
  border-radius: 0;
  background-color: transparent;
  color: var(--v-text);
  box-shadow: inset 0 -1px 0 var(--v-edge);
  padding-inline: 2px;
}
:root [data-slot="field"][data-appearance="inset"] {
  padding: 14px 16px;
  border-radius: min(var(--v-control-radius, 20px), 20px);
  background: var(--v-beige);
  color: var(--v-text);
  box-shadow: inset 0 1px 2px color-mix(in oklab, var(--v-text) 9%, transparent);
  gap: 6px;
}
:root [data-appearance="inset"]:is(.v-input,.v-igroup,.v-textarea,.v-native,.v-select,.v-number-input,.v-multi-select__trigger) {
  background-color: var(--v-beige);
  color: var(--v-text);
  box-shadow: inset 0 1px 2px color-mix(in oklab, var(--v-text) 12%, transparent);
}
:root [data-slot="field"][data-appearance="inset"] :is(.v-input,.v-igroup,.v-textarea):not([data-appearance]) {
  background: transparent;
  box-shadow: none;
  padding-inline: 0;
}
:root [data-slot="field"][data-appearance="inset"] [data-slot="field-label"] { color: var(--v-text-2); }
:root [data-slot="field"][data-appearance="inset"]:focus-within { outline: 2px solid var(--v-brand); outline-offset: 2px; }
:root [data-appearance]:is(.v-input,.v-igroup,.v-textarea,.v-native,.v-select,.v-number-input,.v-multi-select__trigger):focus-within,
:root [data-slot="field"][data-appearance] :is(.v-input,.v-igroup,.v-textarea):focus-within {
  outline: 2px solid var(--v-brand);
  outline-offset: 3px;
}
:root [data-slot="field"][data-appearance="inset"] :is(.v-input,.v-igroup,.v-textarea):focus-within { outline: none; }
:root [data-appearance]:is(.v-input,.v-igroup,.v-textarea,.v-native,.v-select,.v-number-input,.v-multi-select__trigger):is(:disabled,[data-disabled="true"],:has(input:disabled)),
:root [data-slot="field"][data-appearance] :is(.v-input,.v-igroup,.v-textarea):is(:disabled,:has(input:disabled)) {
  background: var(--v-disabled-face);
  color: var(--v-disabled-ink);
  box-shadow: inset 0 0 0 1px var(--v-disabled-edge);
  cursor: not-allowed;
}
:root [data-slot="field"][data-appearance][data-state="error"],
:root [data-appearance]:is(.v-input,.v-igroup,.v-textarea,.v-native,.v-select,.v-number-input,.v-multi-select__trigger):is([aria-invalid="true"],[data-invalid="true"],:has([aria-invalid="true"])) {
  outline: 2px solid var(--v-danger-fill);
  outline-offset: 3px;
}
:root [data-slot="field"][data-appearance][data-state="error"] [role="alert"] { color: var(--v-danger-ink); }

.v-form-example { display: grid; gap: 20px; width: 100%; min-width: 0; max-width: 480px; margin-inline: auto; }
.v-form-example__intro { display: grid; gap: 5px; }
.v-form-example__intro strong { font-family: var(--font-display, inherit); font-size: 22px; font-weight: 500; }
.v-form-example__intro p { margin: 0; color: var(--v-text-2); font-size: 13px; line-height: 1.5; }
.v-form-example__status { min-height: 1.5em; margin: 0; font-size: 12px; color: var(--v-text-2); overflow-wrap: anywhere; }
.v-form-example__footer { display: flex; gap: 10px; align-items: center; justify-content: space-between; }

/* Composer owns one surface, while the actual textarea keeps native editing. */
:root .v-composer[data-appearance] { border-radius:min(var(--v-control-radius,20px),20px); background:var(--v-canvas); color:var(--v-text); box-shadow:inset 0 0 0 1px var(--v-edge); }
:root .v-composer[data-appearance="inset"] { background:var(--v-beige); box-shadow:inset 0 1px 2px color-mix(in oklab,var(--v-text) 12%,transparent); }
:root .v-composer[data-appearance="editorial"] { border-radius:0; background:transparent; box-shadow:inset 0 -1px 0 var(--v-edge); }
:root .v-composer[data-appearance] .v-textarea:is(:focus,:hover,:not(:focus)) { background:transparent; box-shadow:none; outline:0; border-radius:0; resize:vertical; }
:root .v-composer[data-appearance] .v-textarea-scroll > textarea { padding-inline-end:30px; }
:root [data-slot="field"][data-appearance] [data-slot="input-group"] .v-textarea { background:transparent; box-shadow:none; outline:0; border:0; border-radius:0; }
:root .v-composer[data-appearance]:focus-within { outline:2px solid var(--v-brand); outline-offset:3px; }
:root [data-slot="field"][data-appearance="inset"] .v-composer[data-appearance] { background:transparent; box-shadow:none; outline:0; }
.v-form-example[data-form-example="field"] { max-width:600px; }
.v-form-example [data-slot="field-label"] { font-size:14px; line-height:1.5; }
.v-form-example [data-slot="field-description"] { font-size:13px; margin:0; }
.v-form-example__footer > .v-btn, .v-form-example [data-slot="textarea-composer-bar"] > .v-btn { min-height:44px; }
.v-form-example [data-slot="textarea-composer-bar"] { justify-content:space-between; flex-wrap:wrap; gap:12px; padding:10px 12px; border-top:1px solid var(--v-border); }
.v-form-example__allowance { height:4px; border-radius:4px; overflow:hidden; background:var(--v-beige); margin-top:-8px; }
.v-form-example__allowance > span { display:block; height:100%; max-width:100%; border-radius:inherit; background:var(--v-blue-deep); }
.v-form-example__label-row { display:flex; align-items:baseline; flex-wrap:wrap; gap:8px; justify-content:space-between; }
.v-form-example__label-row > span { font-size:12px; color:var(--v-text-2); }
.v-form-example__hint { margin:0; color:var(--v-text-2); font-size:13px; line-height:1.5; }
/* Editorial draws only the focus edge: no moving caret, label or hit area. */
:root [data-appearance="editorial"]:is(.v-input,.v-igroup,.v-textarea,.v-composer),
:root [data-slot="field"][data-appearance="editorial"] :is(.v-input,.v-igroup,.v-textarea):not([data-appearance]) {
  background-image:linear-gradient(var(--v-brand),var(--v-brand)); background-repeat:no-repeat; background-position:left bottom; background-size:0% 2px;
  transition:background-size var(--t-micro) var(--enter);
}
:root [data-appearance="editorial"]:is(.v-input,.v-igroup,.v-textarea,.v-composer):focus-within,
:root [data-slot="field"][data-appearance="editorial"] :is(.v-input,.v-igroup,.v-textarea):focus-within { background-size:100% 2px; outline:0; }
@media(prefers-reduced-motion:reduce) { :root [data-slot="field"] :is(.v-input,.v-igroup,.v-textarea,.v-composer) { transition:none; } }

}
